import math
from scipy.optimize import brentq

def clamp(N,b,T,X):
 s=X/b; p=dp=0.
 for k in range(N+1):
  q=s+N-2*k
  if q>0:
   p += (-1)**k*math.comb(N,k)*q**(N-1)
   dp += (-1)**k*math.comb(N,k)*(N-1)*q**(N-2)
 return -T/b*dp/p

def L(z):
 if abs(z)<1e-4:return z/3-z**3/45+2*z**5/945
 return 1/math.tanh(z)-1/z
def inv(r): return brentq(lambda z:L(z)-r,1e-12,2/(1-r))
for N in [4,8,12]:
 for a in [.15,.3,.6]:
  b=1.06;T=1;X=N*a
  print(N,a,clamp(N,b,T,X),T/b*inv(a/b))
PY"

